// Exam 3 words for the map's Words tab and the Mastery test's "Words in this question", put ahead of the shared glossary
// (data/glossary.js) so a question's own Exam 3 words come first in the 14-word list. Each entry: [term, [the spellings that find it in the text], plain-language meaning].
// A spelling in lowercase matches anywhere, any case; one with capitals matches exactly; a short all-caps
// abbreviation matches only as a whole word.
window.GLOSSARY = [].concat([
 // Fluids and electrolytes (ch 13)
 ["Isotonic / hypotonic / hypertonic", ["sotonic", "ypotonic", "ypertonic"], "How concentrated a fluid is compared with blood (270–300 mOsm/L). Isotonic stays in the vessels and tissues; hypotonic moves water into cells; hypertonic pulls water out of cells."],
 ["Crystalloid / colloid", ["rystalloid", "olloid"], "Crystalloids (saline, lactated Ringer’s, dextrose) are water with small particles that spread through every compartment; colloids such as albumin are large molecules that stay in the blood."],
 ["Interstitial fluid", ["nterstitial"], "Fluid in the spaces between cells — the body’s buffer, filled (edema) or drained to protect the blood and the cells."],
 ["Hypovolemia / hypervolemia", ["ypovolemi", "ypervolemi"], "Too little / too much fluid in the blood vessels."],
 ["Hyponatremia / hypernatremia", ["yponatremi", "ypernatremi"], "Sodium too low (under 136) / too high (over 145). It shows mostly in the brain: confusion, then seizures and coma."],
 ["Hypomagnesemia / hypermagnesemia", ["ypomagnes", "ypermagnes"], "Magnesium too low (under 1.3) / too high (over 2.1). Low: twitching, hyperactive reflexes, dysrhythmias. High: fading reflexes, a slow heart, weak breathing."],
 ["Specific gravity", ["pecific gravity"], "How concentrated urine is. Above 1.030 means the kidneys are holding on to water — a sign of dehydration."],
 ["Skin turgor", ["urgor"], "How fast pinched skin flattens. Skin that stays tented suggests dehydration; in older adults test over the sternum, not the hand."],
 ["Hemoconcentration / hemodilution", ["emoconcentrat", "emodilut"], "Blood made more concentrated by water loss (Hct, BUN and sodium rise) / more dilute by extra water (Hgb and Hct fall)."],
 ["Insensible water loss", ["nsensible"], "Water lost without our control — through the skin, lungs and stool — about 500–1000 mL a day, more with fever and fast breathing."],
 ["Obligatory urine output", ["bligatory"], "The least urine (400–600 mL a day) that can still clear the body’s wastes."],
 ["Natriuretic peptides (ANP, BNP)", ["atriuretic", "ANP"], "Hormones a stretched heart releases that make the kidneys lose sodium and water — the opposite of aldosterone."],
 ["SIADH", ["SIADH"], "Syndrome of inappropriate antidiuretic hormone: too much ADH makes the kidneys hold water, diluting the sodium."],
 ["U wave", ["U wave"], "A small bump after the T wave on the ECG — a sign of low potassium."],
 ["Peaked T waves", ["eaked T", "all, peaked"], "Tall, narrow T waves on the ECG — the early warning of high potassium."],
 ["Salt substitute", ["alt substitute"], "A table-salt replacement made of potassium chloride — dangerous with kidney disease, ACE inhibitors or potassium-sparing diuretics."],
 ["Infiltration (IV)", ["nfiltration"], "IV fluid leaking out of the vein into the tissue around it: swelling, coolness, pain and a slowing drip. With potassium: stop, remove the catheter, notify."],
 // Acid–base (ch 14)
 ["Buffer", ["buffers", "buffering", "bicarbonate buffer", "Buffer"], "A chemical that soaks up extra hydrogen ions or releases them to keep the pH steady — bicarbonate, phosphate and proteins such as hemoglobin."],
 ["Compensation (acid–base)", ["ully compensated", "artly compensated", "ncompensated", "espiratory compensation", "idney compensation"], "The organ that didn’t cause an imbalance pushing the pH back toward normal: the lungs change the CO₂ in minutes, the kidneys change the bicarbonate over 24–48 hours."],
 ["Carbonic anhydrase", ["arbonic anhydrase"], "The enzyme that joins CO₂ and water into carbonic acid, which splits into H⁺ and bicarbonate — why more CO₂ means more acid."],
 ["Hyperventilation / hypoventilation", ["yperventilat", "ypoventilat"], "Breathing faster and deeper than needed, blowing off CO₂ (alkalosis) / slower and shallower, keeping CO₂ (acidosis)."],
 ["ROME", ["ROME"], "Memory aid for blood gases: Respiratory Opposite (pH and PaCO₂ move opposite ways), Metabolic Equal (pH and HCO₃⁻ move the same way)."],
 ["Combined acidosis", ["ombined acidosis", "ombined respiratory and metabolic", "ixed acidosis"], "Respiratory and metabolic acidosis at once (for example DKA in someone with COPD): neither organ can cover for the other, so the pH falls further."],
 // Infusion therapy (ch 15)
 ["Vesicant", ["esicant"], "A drug that destroys tissue if it leaks out of the vein: blistering, sloughing and necrosis. Examples: dopamine and many chemotherapy drugs."],
 ["Irritant (IV drug)", ["rritant"], "A drug that inflames the vein lining from the inside and causes phlebitis, such as amiodarone, vancomycin or ciprofloxacin."],
 ["Extravasation", ["xtravasat"], "A vesicant leaking from the vein into the tissue. It can blister and destroy the tissue, sometimes days later."],
 ["Phlebitis", ["hlebitis"], "An inflamed vein: pain, redness, warmth and a hard, cordlike vein, caused by the catheter, a harsh drug or bacteria."],
 ["PICC", ["PICC"], "Peripherally inserted central catheter: put in through an arm vein, with its tip in the superior vena cava. It can take any IV fluid or drug."],
 ["Midline catheter", ["idline catheter", "idlines"], "A 3–8-inch catheter in an upper-arm vein whose tip stays in the arm (no farther than the axillary vein). It follows peripheral rules: no vesicants, no TPN."],
 ["Implanted port", ["mplanted port", "chest port"], "A small reservoir with a self-sealing top, placed under the skin and joined to a central catheter. It is reached with a noncoring needle."],
 ["Noncoring (Huber) needle", ["oncoring", "Huber"], "A needle with a bent tip that slips through a port’s rubber top without cutting out a core, so the port keeps sealing."],
 ["Cavoatrial junction", ["avoatrial"], "Where the superior vena cava meets the right atrium: the target for the tip of every central line, where fast blood flow dilutes the infusate."],
 ["CRBSI", ["CRBSI", "atheter-related bloodstream"], "Catheter-related bloodstream infection: organisms from the skin or a hub travel on the catheter into the blood. Fever and chills come first, then sepsis."],
 ["Fibrin sheath", ["ibrin sheath"], "A sleeve of fibrin that can form around a catheter tip. Fluid may go in but blood won’t come back, and a drug can leak backward into the tissue."],
 ["Luer-Lok", ["Luer"], "A threaded connection that screws together so tubing can’t pull apart. It matters most on central lines, to prevent air embolism and bleeding."],
 ["Scrub the hub", ["crub the hub"], "Scrubbing a needleless connector with alcohol or chlorhexidine–alcohol, twisting, before every access, to kill organisms in its crevices."],
 ["Speed shock", ["peed shock"], "A drug pushed into a vein too fast reaches a toxic level: dizziness, chest tightness, a flushed face and an irregular pulse."],
 ["Catheter embolism", ["atheter embolism"], "A piece of catheter breaks off and travels in the blood. Apply a tourniquet high on the limb and notify the provider at once."],
 ["Hypodermoclysis", ["ypodermoclysis"], "A slow infusion of isotonic fluid into the fat under the skin, for steady rehydration when veins are poor. It is not for emergencies."],
 ["Intraosseous (IO)", ["ntraosseous"], "Into the bone marrow, usually of the upper tibia. Marrow absorbs like a vein, so IO access is used in emergencies when no vein can be found."],
 ["Epidural / intrathecal", ["pidural", "ntrathecal"], "Epidural: outside the dura that covers the spinal cord. Intrathecal: into the spinal fluid itself, so doses are much smaller."],
 ["Compartment syndrome", ["ompartment syndrome"], "Pressure building in a closed muscle compartment cuts off its blood supply: swelling, coolness, mottling. It is an emergency."],
 ["Gauge (catheter size)", ["-gauge", " gauge"], "The size of a needle or catheter. The bigger the number, the smaller the catheter: 24 g is small, 14 g is large."],
 ["Valsalva maneuver", ["alsalva"], "Holding the breath and bearing down. It raises the pressure in the chest so air can’t be drawn into a vein while a central line is removed."],
 // Inflammation and immunity (ch 16)
 ["Innate / adaptive immunity", ["nnate", "daptive immun"], "Innate immunity is present from birth and acts the same way against everything (skin, inflammation). Adaptive immunity is learned and specific, and it remembers (antibodies, T cells)."],
 ["Active / passive immunity", ["ctive immun", "assive immun"], "Active: your own body makes the antibodies, after an illness or a vaccine; slow to build but lasting. Passive: ready-made antibodies from someone else; immediate but short-lived."],
 ["Antigen", ["ntigen"], "Anything the immune system recognizes as foreign, such as a protein on a germ, a donor organ or an allergen."],
 ["Antibody (immunoglobulin)", ["ntibod", "mmunoglobulin"], "A Y-shaped protein made by plasma cells. It grips one specific antigen and marks it for destruction."],
 ["Human leukocyte antigens (HLA)", ["HLA", "uman leukocyte antigen"], "The tissue-type markers on your cells, matched exactly only by an identical twin. They tell immune cells what is self."],
 ["Left shift", ["eft shift", "andemia"], "More immature neutrophils (bands) than usual on the differential. The marrow can’t keep up with an infection, so sepsis is a risk."],
 ["Phagocytosis", ["hagocyt"], "A white cell engulfing and digesting a germ or debris. A neutrophil does it once; a macrophage, many times."],
 ["Opsonin", ["psonin"], "A coating (an antibody or complement) that makes a germ “sticky” so phagocytes can grab it."],
 ["Complement", ["omplement cascade", "omplement fixation", "omplement proteins", "ctivate complement", "ctivates complement"], "A group of 20 blood proteins that, once triggered, punch holes in invaders and help phagocytes destroy them."],
 ["Plasma cell / memory cell", ["lasma cell", "emory cell"], "Plasma cells are B cells that pour out antibody (up to 300 molecules a second). Memory cells wait for the next exposure and then respond fast."],
 ["Anamnestic response", ["namnestic"], "The fast, large antibody response that memory cells give on a second exposure. It is why you usually don’t get the same illness twice."],
 ["Helper, cytotoxic and regulatory T cells", ["elper T", "ytotoxic T", "egulatory T", "Tregs"], "Helper (CD4+) T cells organize all immunity. Cytotoxic T cells kill virus-infected cells and grafts. Regulatory T cells hold immunity back so it doesn’t attack the body."],
 ["Natural killer (NK) cell", ["atural killer", "NK"], "A lymphocyte that destroys cancer cells and virus-infected cells without being sensitized first."],
 ["Colony-stimulating factor", ["olony-stimulating", "G-CSF", "GM-CSF"], "A growth factor that tells the marrow to make more white cells. G-CSF is given after chemotherapy to rebuild the neutrophils."],
 ["Cardinal signs of inflammation", ["ardinal sign"], "Warmth, redness, swelling, pain and loss of function. They are the same for any injury or infection."],
 ["Immunocompetent", ["mmunocompetent"], "Having an immune system whose parts all work, for full protection."],
 ["Microbiome", ["icrobiome"], "The normal bacteria and fungi on the skin and in the gut, mouth and vagina. While they stay where they belong, they help keep germs out."],
 ["Convalescent plasma", ["onvalescent plasma"], "Plasma rich in antibodies from people who recovered from an infection (such as COVID-19), given as passive immunity."],
 ["Antitoxin / immune globulin", ["ntitoxin", "mmune globulin"], "Ready-made antibodies injected for immediate, short-term protection after an exposure (tetanus, rabies, snake venom)."],
 // Allergy and immunity (ch 17)
 ["Hypersensitivity types I–IV", ["Type I", "ypersensitivity reaction", "ypes of hypersens"], "Type I: IgE and histamine, within an hour (hives, anaphylaxis). Type II: antibodies destroy cells (a wrong-blood transfusion). Type III: immune complexes lodge in vessels (lupus). Type IV: T cells, 12–72 hours later (poison ivy)."],
 ["Allergen", ["llergen"], "A harmless substance (pollen, peanuts, latex, venom) that triggers an allergic reaction only in people who are sensitized to it."],
 ["Anaphylaxis", ["naphyla"], "A body-wide type I reaction: within minutes the vessels dilate and the airways tighten, causing low blood pressure, wheezing and swelling. Give IM epinephrine first."],
 ["Angioedema", ["ngioedema"], "Deep swelling of the lips, tongue, face or throat, often caused by ACE inhibitors through bradykinin. The danger is the airway."],
 ["Urticaria (hives)", ["rticaria", "hives", "wheals"], "Raised, itchy red welts from histamine released in the skin."],
 ["Epinephrine autoinjector", ["utoinjector"], "A spring-loaded pen that injects a set dose of epinephrine into the outer thigh. People at risk carry two."],
 ["Autoimmunity", ["utoimmun"], "The immune system attacking the body’s own healthy tissue because self-tolerance has failed."],
 ["Systemic lupus erythematosus (SLE)", ["upus", "SLE"], "An autoimmune disease in which immune complexes inflame the skin, joints, kidneys, heart and vessels, with flares and remissions."],
 ["Malar (butterfly) rash", ["alar rash", "utterfly rash"], "A red, scaly rash across the cheeks and nose, often after sun exposure. It is a classic sign of lupus."],
 ["Photosensitivity", ["hotosensitiv"], "Skin that reacts to sunlight with a rash or burn. In lupus, UV light can set off a flare."],
 ["Lupus nephritis", ["upus nephritis", "lomerulonephritis"], "Kidney inflammation from lupus immune complexes. Protein leaks into the urine and makes it foamy."],
 ["ANA (antinuclear antibody)", ["ANA", "ntinuclear"], "A blood test for autoantibodies against cell nuclei. It is positive in SLE but never enough on its own to diagnose it."],
 ["Raynaud phenomenon", ["aynaud"], "Fingers that turn white or blue, then red, in the cold as small arteries spasm."],
 ["Retrovirus", ["etrovirus"], "A virus such as HIV that carries its genes as RNA and uses reverse transcriptase to write them into the host cell’s DNA."],
 ["CD4+ T cell", ["CD4"], "The helper T cell that HIV infects. A normal count is 600–1500 cells/mm³; below 200 means stage III (AIDS)."],
 ["Viral load", ["iral load"], "The number of HIV copies in 1 mL of blood. It is the best guide to how active the virus is and whether the drugs are working."],
 ["Seroconversion window", ["eroconver"], "The weeks after infection before antibodies can be detected. A test in that window can be falsely negative."],
 ["Opportunistic infection", ["pportunistic"], "An infection from an organism that a healthy immune system keeps in check (Candida, Pneumocystis, Toxoplasma). It takes hold when immunity fails."],
 ["AIDS (stage III HIV)", ["AIDS"], "HIV plus a CD4+ count under 200 cells/mm³ or an AIDS-defining infection or cancer. The diagnosis is permanent."],
 ["Pneumocystis pneumonia", ["neumocystis"], "A fungal lung infection in people with very low CD4+ counts: a dry cough, breathlessness and low oxygen. It is treated with trimethoprim-sulfamethoxazole."],
 ["Kaposi sarcoma", ["aposi"], "A tumor of small blood vessels seen in AIDS. It appears as pink, red, purple or brown raised lesions on the skin."],
 ["cART", ["cART"], "Combination antiretroviral therapy: several HIV drugs from different classes that control the virus but don’t kill it."],
 ["PrEP / PEP / TasP", ["PrEP", "PEP", "TasP"], "PrEP: HIV drugs taken before an exposure by an HIV-negative person. PEP: a 28-day course started within 72 hours after an exposure. TasP: treating a person with HIV so the virus can’t be passed on."],
 ["IRIS", ["IRIS"], "Immune reconstitution inflammatory syndrome: as cART restores the T cells, they overreact to hidden infections, causing fever, night sweats and worse illness. cART continues."],
 ["HIV wasting syndrome", ["asting syndrome"], "An unplanned loss of 10% or more of body weight and muscle in HIV."],
 ["HLA-B∗5701 and Trofile tests", ["HLA-B", "rofile"], "Genetic tests before some HIV drugs: HLA-B∗5701 before abacavir (risk of a hypersensitivity reaction), and Trofile before maraviroc (the drug needs CCR5 receptors)."],
 ["Lyme disease", ["Lyme"], "A tick-borne infection (Borrelia burgdorferi). A bull’s-eye rash comes first, then joint, heart and nerve problems if it goes untreated."],
 ["Erythema migrans", ["rythema migrans", "ull’s-eye"], "The expanding bull’s-eye rash of early Lyme disease."],
 ["Hyperacute rejection", ["yperacute"], "Rejection within minutes to hours of a transplant, from antibodies the recipient already had. It can’t be stopped, and the organ is removed."],
 ["Calcineurin inhibitor", ["alcineurin"], "A class of anti-rejection drugs (cyclosporine, tacrolimus) that blocks T-cell activation. Teach to avoid grapefruit with cyclosporine."],
 // GI tract: anatomy, exam and labs (ch 45)
 ["Peristalsis", ["eristal"], "Waves of muscle squeezing that push food and stool along the gut. Bowel sounds are the noise it makes moving gas and fluid."],
 ["Chyme", ["chyme"], "The soupy mix of food, acid and enzymes the stomach sends into the small intestine."],
 ["Peritoneum", ["eritoneum", "eritoneal"], "The smooth lining of the abdomen that also covers the organs. It holds a little fluid so organs glide; when inflamed it makes the abdominal muscles go rigid."],
 ["Borborygmi", ["orborygm"], "Loud, high-pitched rushing bowel sounds — the bowel working hard, as with diarrhea or above a blockage."],
 ["Bruit", ["bruit"], "A whooshing sound over an artery from turbulent blood flow. Over the abdominal aorta it can mean an aneurysm — don’t palpate."],
 ["Guarding vs rigidity", ["uarding", "igidity", "rigid"], "Guarding is tensing the abdomen on purpose to protect a sore spot. Rigidity is involuntary, boardlike tightness — a sign of an inflamed peritoneum."],
 ["Rebound tenderness", ["ebound tenderness"], "Pain when pressure on the abdomen is suddenly released — a sign the peritoneum is inflamed."],
 ["Tympany / dullness", ["ympany", "dullness"], "Percussion sounds: tympany is drum-like over gas-filled bowel; dullness is a thud over solid organs, fluid or a mass."],
 ["Steatorrhea", ["teatorrhea"], "Fatty, pale, bulky, foul-smelling stool that floats — fat wasn’t digested or absorbed (low lipase, celiac disease, Crohn’s)."],
 ["Jaundice", ["aundice"], "Yellow skin and eyes from bilirubin building up — liver disease, blocked bile ducts or red cells breaking down."],
 ["Ammonia", ["mmonia"], "A toxic waste from protein that the liver normally turns into urea. A failing liver lets it rise and cause confusion."],
 ["Albumin", ["lbumin"], "The main protein in the blood, made by the liver. Low albumin (liver disease, malnutrition) lets fluid leak into tissues."],
 ["ALT / AST", ["ALT", "AST"], "Liver enzymes that leak into the blood when liver cells are damaged — highest in hepatitis."],
 ["Amylase / lipase", ["mylase", "lipase"], "Pancreatic digestive enzymes that leak into the blood in acute pancreatitis."],
 ["Alkaline phosphatase", ["lkaline phosphatase"], "An enzyme that rises when bile can’t drain (obstruction) or with liver tumors."],
 ["CEA", ["CEA"], "Carcinoembryonic antigen, a blood tumor marker. Used to track colorectal cancer treatment and recurrence — not to diagnose."],
 ["FIT / gFOBT", ["FIT", "FOBT", "uaiac"], "Home stool tests for hidden blood. FIT needs no diet changes; the guaiac test (gFOBT) needs no NSAIDs, red meat or high-dose vitamin C. Any positive result → colonoscopy."],
 ["EGD", ["EGD", "sophagogastroduodenoscopy"], "A scope through the mouth into the esophagus, stomach and duodenum. The throat is numbed, so nothing by mouth until the gag reflex returns."],
 ["ERCP", ["ERCP"], "A scope plus dye to see and treat the bile and pancreatic ducts (for example, to remove a gallstone). Pancreatitis can appear up to 2 days later."],
 ["Colonoscopy / sigmoidoscopy", ["olonoscop", "igmoidoscop"], "A flexible scope through the whole colon (colonoscopy) or only the rectum and sigmoid (sigmoidoscopy) to look, biopsy and remove polyps."],
 ["Capsule endoscopy", ["apsule endoscopy", "ideo capsule"], "Swallowing a pill-sized camera that photographs the small intestine as it passes."],
 ["Moderate sedation", ["oderate sedation", "onscious sedation"], "Drugs such as midazolam, fentanyl or propofol that make a patient drowsy but responsive for a procedure. They can slow breathing."],
 ["Sternal rub", ["ternal rub"], "Rubbing the breastbone firmly with the knuckles to rouse a patient who is breathing too slowly under sedation."],
 ["Bowel prep", ["owel prep"], "Drinking a large volume of laxative solution, with clear liquids only, to empty the colon before a colonoscopy or surgery."],
 ["Clear liquid diet", ["lear liquid"], "Liquids you can see through — water, broth, clear juice, gelatin (not red, orange or purple) — that leave little residue."],
 // Mouth and esophagus (ch 46)
 ["Stomatitis", ["tomatitis"], "Inflammation and sores in the mouth — from chemotherapy, radiation, infection or irritants."],
 ["Aphthous ulcer", ["phthous", "anker sore"], "A canker sore — a painful, shallow ulcer in the mouth."],
 ["Candidiasis (thrush)", ["andidiasis", "thrush", "Candida"], "A yeast overgrowth: white patches that wipe off and leave a red, sore base. Common after antibiotics or with a weak immune system."],
 ["Leukoplakia", ["eukoplakia"], "Thick white patches in the mouth that can’t be scraped off — linked to tobacco; they can become cancer."],
 ["Erythroplakia", ["rythroplakia"], "Red, velvety patches in the mouth — precancerous."],
 ["Xerostomia", ["erostomia", "ry mouth"], "Dry mouth from too little saliva — after radiation or from some drugs."],
 ["Sialadenitis", ["ialadenitis"], "Inflammation of a salivary gland."],
 ["Glossectomy / mandibulectomy", ["lossectomy", "andibulectomy"], "Removing part of the tongue / part of the jawbone, for oral cancer."],
 ["Dysphagia", ["ysphagia"], "Difficulty swallowing — food “sticks”. A risk for aspiration and malnutrition; progressive dysphagia is a red flag for cancer."],
 ["Odynophagia", ["dynophagia"], "Pain when swallowing."],
 ["GERD", ["GERD", "astroesophageal reflux"], "Gastroesophageal reflux disease: stomach acid keeps flowing back into the esophagus and inflames it."],
 ["LES (lower esophageal sphincter)", ["LES", "ower esophageal sphincter"], "The ring of muscle at the bottom of the esophagus that keeps stomach contents from flowing back up."],
 ["Pyrosis (heartburn)", ["yrosis", "eartburn"], "A burning feeling behind the breastbone from stomach acid in the esophagus."],
 ["Dyspepsia", ["yspepsia"], "Indigestion — burning, fullness or discomfort in the upper abdomen."],
 ["Regurgitation", ["egurgitat"], "Stomach contents coming back up into the throat or mouth without vomiting."],
 ["Water brash", ["ater brash"], "A sudden rush of saliva into the mouth without a sour taste — a reflex response to reflux."],
 ["Eructation", ["ructation"], "Belching."],
 ["Barrett esophagus", ["arrett"], "Esophageal lining that changes to stomach-type cells after years of acid reflux — a precancerous change."],
 ["Esophagitis", ["sophagitis"], "Inflammation of the esophagus, usually from acid reflux."],
 ["Hiatal hernia", ["iatal hernia", "araesophageal"], "Part of the stomach slides or rolls up through the diaphragm into the chest. Sliding hernias cause reflux; paraesophageal ones can twist and strangulate."],
 ["Fundoplication (Nissen)", ["undoplication", "Nissen"], "Surgery that wraps the top of the stomach around the lower esophagus to stop reflux."],
 ["Gas bloat syndrome", ["as bloat"], "After fundoplication, being unable to burp up swallowed air — the stomach fills with gas and hurts."],
 ["Esophagectomy", ["sophagectomy"], "Removing all or part of the esophagus, usually for cancer; the stomach is pulled up and joined to what remains."],
 ["Anastomosis", ["nastomos"], "A surgical join between two cut ends of the gut (or of vessels). A leak at the join spills gut contents."],
 ["Mediastinitis", ["ediastinitis"], "Infection in the middle of the chest around the heart and esophagus — can follow an esophageal leak and is often fatal."],
 ["Caustic", ["austic"], "Corrosive — able to burn tissue. Swallowed caustics (acids, lye) burn the mouth and esophagus, and alkalis burn deeper; intestinal fluid from a fistula or ileostomy is caustic to skin."],
 // Stomach (ch 47)
 ["Gastritis", ["astritis"], "Inflamed stomach lining — often from NSAIDs, alcohol or H. pylori."],
 ["Peptic ulcer", ["eptic ulcer", "PUD"], "A sore eroded through the lining of the stomach (gastric) or duodenum (duodenal) by acid and pepsin."],
 ["H. pylori", ["pylori"], "A spiral bacterium that lives under the stomach’s mucus, causes most ulcers and raises stomach cancer risk. Treated with a PPI plus antibiotics."],
 ["Urease / urea breath test", ["urease", "rea breath"], "H. pylori’s enzyme that splits urea into ammonia (to survive acid) and CO₂ — the breath test detects that CO₂."],
 ["Stress ulcer (Curling, Cushing)", ["tress ulcer", "urling ulcer", "ushing ulcer"], "Sudden ulcers after severe physical stress — burns (Curling), head injury or raised ICP (Cushing), sepsis, surgery. The main sign is bleeding."],
 ["Melena", ["melena"], "Black, tarry, sticky stool from blood digested on its way through the gut — bleeding in the upper GI tract."],
 ["Hematemesis", ["ematemesis"], "Vomiting blood. Bright red means fast, fresh bleeding; dark “coffee grounds” means blood that sat in stomach acid."],
 ["Coffee-ground emesis", ["offee-ground", "offee ground"], "Dark brown, grainy vomit — blood partly digested by stomach acid; slower or older upper GI bleeding."],
 ["Hematochezia", ["ematochezia"], "Bright red blood passed from the rectum — usually bleeding low in the colon or rectum."],
 ["Perforation", ["erforat"], "A hole through the full thickness of the gut wall; contents spill into the abdomen → peritonitis. Sudden severe pain, rigid abdomen."],
 ["Pyloric (gastric outlet) obstruction", ["yloric obstruction", "astric outlet"], "Scarring or swelling blocks the stomach’s exit — vomiting of old food, metabolic alkalosis, low potassium."],
 ["Gastrectomy", ["astrectomy"], "Surgical removal of part (subtotal) or all (total) of the stomach."],
 ["Dumping syndrome", ["dumping"], "After gastric surgery food rushes into the small intestine: early (within 20 minutes) dizziness, fast heart, sweating; late (1–3 hours) low blood sugar."],
 ["Pernicious anemia", ["ernicious"], "Anemia from being unable to absorb vitamin B₁₂ because intrinsic factor is missing (stomach damage or removal). Treated with B₁₂ injections."],
 ["Atrophic glossitis", ["lossitis", "eefy tongue"], "A smooth, red, “beefy” tongue — a sign of B₁₂ deficiency."],
 ["Acute gastric dilation", ["astric dilation"], "After gastric surgery, a blocked NG tube lets the stomach balloon: epigastric pain, hiccups, tachycardia, low BP."],
 ["Pancreatitis", ["ancreatitis"], "Inflammation of the pancreas, often from alcohol or gallstones (or after ERCP) — severe epigastric pain into the back; amylase and lipase rise."],
 // Bowel: obstruction, cancer, IBS, hernias (ch 48)
 ["Ileus", ["ileus"], "The bowel stops moving without a physical blockage (paralytic ileus) — after surgery, with low potassium or with peritonitis."],
 ["Bowel obstruction", ["owel obstruction", "ntestinal obstruction"], "Something blocks the bowel (mechanical — adhesions, tumor, hernia, twisting) or it stops moving (paralytic). Contents back up, the wall swells and fluid is lost."],
 ["Adhesions", ["dhesion"], "Bands of scar tissue inside the abdomen after surgery that can kink or trap the bowel — the most common cause of small-bowel obstruction."],
 ["Volvulus", ["olvulus"], "The bowel twisting on itself, cutting off its contents and its blood supply."],
 ["Intussusception", ["ntussusception"], "One part of the bowel telescoping into the next."],
 ["Strangulation", ["trangulat"], "Squeezing that cuts off blood flow. Bowel trapped tightly in a hernia ring or a twist loses its blood supply and dies within hours."],
 ["Obstipation", ["bstipation"], "Severe constipation — no stool or gas passing at all, as with a complete obstruction."],
 ["Flatus", ["flatus"], "Passing gas from the rectum. After surgery it is the best sign the bowel is moving again."],
 ["Salem sump tube", ["alem sump"], "A double-lumen NG tube for suction; its blue air vent (“pigtail”) keeps the stomach lining from being sucked into the tube."],
 ["Decompression", ["ecompress"], "Relieving pressure — removing trapped air and fluid with NG suction from a swollen stomach or bowel, or (in Graves eye disease) surgery that makes room behind the eye."],
 ["Polyp / adenoma", ["olyps", "olyp ", "olyp,", "olyp.", "olypectomy", "olyposis", "denoma"], "A growth on a lining or in a gland. An adenoma is a benign growth of gland tissue — a parathyroid adenoma makes too much PTH; adenomatous colon polyps can slowly turn into cancer, which is why colonoscopy removes them."],
 ["FAP", ["FAP", "amilial adenomatous"], "Familial adenomatous polyposis: an inherited gene change causing thousands of colon polyps and nearly certain cancer — the colon is usually removed by about age 20."],
 ["Lynch syndrome", ["ynch syndrome", "HNPCC"], "An inherited problem with DNA repair that raises the risk of colon, uterine and other cancers."],
 ["Colostomy", ["olostomy"], "Part of the colon brought out through the abdomen as a stoma. The farther along the colon, the more formed the stool."],
 ["Stoma", ["stoma ", "stomas", "stoma,", "stoma."], "The opening of bowel on the abdomen. Healthy: moist and pink to red. Dark, purple, black or dry means its blood supply is failing."],
 ["Mucocutaneous separation", ["ucocutaneous"], "The stitched join between the stoma and the skin pulling apart."],
 ["Abdominoperineal (AP) resection", ["bdominoperineal", "AP resection"], "Surgery for low rectal cancer that removes the sigmoid colon, rectum and anus through abdominal and perineal incisions — leaves a permanent colostomy."],
 ["CWOCN", ["CWOCN", "ostomy and continence nurse"], "Certified wound, ostomy and continence nurse — marks the stoma site and teaches ostomy care."],
 ["Irritable bowel syndrome (IBS)", ["IBS", "rritable bowel"], "Chronic abdominal pain with diarrhea, constipation or both, but no visible damage. Linked to stress and an oversensitive gut."],
 ["Visceral hypersensitivity", ["isceral hypersensitiv"], "Gut nerves that signal pain for normal amounts of stretch or gas — part of IBS."],
 ["Hydrogen breath test", ["ydrogen breath"], "Breathing into bags after drinking a test sugar; extra hydrogen means gut bacteria are fermenting it (overgrowth) or it wasn’t absorbed."],
 ["Hernia", ["hernia"], "Bowel or other tissue pushing through a weak spot in the abdominal wall (groin, navel, old incision) or the diaphragm (hiatal)."],
 ["Incarcerated hernia", ["ncarcerat", "rreducible"], "A hernia that can’t be pushed back in. It needs urgent surgical evaluation because it can strangulate."],
 ["Herniorrhaphy / hernioplasty", ["erniorrhaphy", "ernioplasty"], "Hernia repair: herniorrhaphy sews the weak spot closed; hernioplasty reinforces it with mesh."],
 ["Hemorrhoids", ["emorrhoid"], "Swollen veins in the anal canal that bleed bright red on the toilet paper, itch and can prolapse; worsened by straining."],
 ["Sitz bath", ["itz bath"], "Sitting in a few inches of warm water for 10–20 minutes to ease anal or perineal pain and help healing."],
 ["Kehr sign", ["ehr sign"], "Left shoulder pain from blood irritating the diaphragm — a sign of a ruptured spleen."],
 ["Cullen / Turner sign", ["ullen sign", "urner sign"], "Bruising around the navel (Cullen) or on the flanks (Turner) from bleeding inside or behind the abdomen."],
 ["FAST scan", ["FAST"], "Focused assessment with sonography for trauma: a bedside ultrasound that quickly finds blood or fluid in the abdomen."],
 ["Abdominal compartment syndrome", ["ompartment syndrome"], "Pressure inside the abdomen rising so high that it squeezes the organs and cuts off their blood supply."],
 // Inflammatory bowel conditions (ch 49)
 ["Peritonitis", ["eritonitis"], "Infection or inflammation of the peritoneum — usually from a hole in the gut. Rigid, boardlike abdomen, fever, fast pulse; can lead to septic shock."],
 ["Third spacing", ["hird spac", "hird-spac"], "Fluid leaking out of the blood vessels into places it can’t be used — the abdomen, bowel or tissues. The patient becomes dehydrated without visible fluid loss."],
 ["Appendicitis", ["ppendicitis"], "An inflamed, blocked appendix. Pain starts near the navel and settles in the right lower quadrant; it can burst within 24–36 hours."],
 ["McBurney point", ["cBurney"], "The spot in the right lower quadrant, midway between the umbilicus and the right hip bone, where appendicitis pain settles."],
 ["Fecalith", ["ecalith"], "A hard, stone-like piece of stool that can block the appendix."],
 ["Gastroenteritis", ["astroenteritis"], "Inflammation of the stomach and intestines from a virus or bacteria — vomiting first, then cramps and diarrhea."],
 ["Norovirus", ["orovirus"], "The leading cause of foodborne gastroenteritis. It spreads easily by the fecal-oral route; wash hands with soap and water for at least 30 seconds."],
 ["Fecal-oral route", ["ecal-oral", "ral-fecal"], "How many gut infections spread: organisms from stool reach the mouth on hands, food, water or surfaces."],
 ["Oral rehydration therapy (ORT)", ["ral rehydration", "ORT"], "Drinks with the right mix of sugar and salt (such as Pedialyte): sodium and glucose are absorbed together, and water follows."],
 ["Tenesmus", ["enesmus"], "A painful, urgent feeling of needing to pass stool even when the rectum is empty — common in ulcerative colitis."],
 ["Ulcerative colitis (UC)", ["lcerative colitis"], "Chronic inflammation of the colon lining that starts at the rectum and spreads continuously. Bloody diarrhea with tenesmus; removing the colon cures it."],
 ["Crohn’s disease", ["rohn"], "Chronic inflammation through all layers of the gut, in patches (skip lesions), most often at the end of the small intestine. Fistulas, strictures, malabsorption."],
 ["Inflammatory bowel disease (IBD)", ["IBD", "nflammatory bowel"], "The name for ulcerative colitis and Crohn’s disease together."],
 ["Skip lesions / transmural", ["kip lesion", "ransmural"], "Patches of diseased bowel separated by normal bowel (skip lesions), with inflammation through the whole thickness of the wall (transmural) — typical of Crohn’s."],
 ["Toxic megacolon", ["oxic megacolon"], "A severe complication of colitis: the colon stops moving and swells massively and can perforate. Fever, tachycardia, distention."],
 ["Fistula", ["istula"], "An abnormal tunnel between two organs, or between an organ and the skin — common in Crohn’s disease."],
 ["Fissure", ["issure"], "A small tear in the lining of the anus."],
 ["Stricture", ["tricture"], "A narrowed section of a tube (esophagus, bowel) from scar tissue."],
 ["Ileostomy", ["leostomy"], "The end of the small intestine (ileum) brought out through the abdomen as a stoma. Output is liquid, high-volume and full of enzymes that burn skin."],
 ["J-pouch (IPAA)", ["J-pouch", "pouch–anal", "pouch-anal"], "After the colon is removed, a pouch made from the small intestine is joined to the anus so stool can be passed normally."],
 ["Proctocolectomy", ["roctocolectomy"], "Surgical removal of the colon and rectum."],
 ["Pouchitis", ["ouchitis"], "Inflammation of an ileal J-pouch — treated with metronidazole."],
 ["Diverticula", ["iverticula", "iverticulum"], "Small pouches that bulge out through weak spots in the colon wall, usually the sigmoid."],
 ["Diverticulosis vs diverticulitis", ["iverticulosis", "iverticulitis"], "Diverticulosis: pouches are present, usually without symptoms. Diverticulitis: a pouch is inflamed or infected — LLQ pain, fever, high WBC."],
 ["Celiac disease", ["eliac"], "An autoimmune reaction to gluten that damages the small-intestine lining → diarrhea, malabsorption, weight loss. Treated only by a strict gluten-free diet."],
 ["Gluten", ["luten"], "A protein in wheat, barley and rye — the trigger in celiac disease."],
 ["Villi", ["villi", "villus"], "Tiny finger-like folds lining the small intestine that give it a huge surface for absorbing food."],
 ["Malabsorption", ["alabsorpt"], "Food and nutrients not being absorbed from the gut — weight loss, diarrhea, fatty stool, low vitamin levels."],
 ["Giardiasis", ["iardia"], "A parasite infection, often from untreated water, that inflames the small-intestine lining — diarrhea and malabsorption."],
 ["Amebiasis", ["mebiasis", "mebic", "mebicide"], "An ameba infection that ulcerates the colon — foul diarrhea, sometimes bloody; it can cause a liver abscess."],
 // Liver (ch 50)
 ["Cirrhosis", ["irrhosis", "irrhotic"], "Permanent scarring of the liver. Scar bands and nodules block blood flow through it, and the liver slowly loses its jobs — making albumin and clotting factors, clearing ammonia and bilirubin."],
 ["Portal hypertension", ["ortal hypertension"], "High pressure (10 mm Hg or more) in the portal vein, which carries blood from the gut to the liver. Scar blocks the flow, so blood backs up and detours — causing varices, a big spleen and ascites."],
 ["Ascites", ["scites", "scitic"], "Fluid collecting in the abdomen. In cirrhosis it comes from high portal pressure plus low albumin; it bulges the flanks and can push on the lungs."],
 ["Esophageal varices", ["varice", "ariceal"], "Swollen, thin-walled veins in the lower esophagus (or stomach) that form when portal blood detours around the liver. They can burst and bleed massively."],
 ["Caput medusae", ["aput medusae"], "Swollen veins spreading out from the belly button — blood detouring around a blocked liver through the abdominal wall."],
 ["Splenomegaly / hepatomegaly", ["plenomegaly", "epatomegaly"], "An enlarged spleen / an enlarged liver. In cirrhosis the backed-up spleen destroys platelets; the liver is big early and small and hard later."],
 ["Thrombocytopenia", ["hrombocytopenia"], "A low platelet count, so the person bruises and bleeds easily. In cirrhosis it is often the first lab clue."],
 ["Hepatic encephalopathy", ["ncephalopathy"], "Brain changes from liver failure — ammonia and other toxins the liver should clear reach the brain. It runs from sleep and mood changes to confusion, hand-flapping and coma."],
 ["Asterixis", ["sterixis"], "A coarse \u2018hand-flapping\u2019 tremor: the wrists and fingers jerk up and down when the arms are held out. A sign of worsening hepatic encephalopathy."],
 ["Fetor hepaticus", ["etor hepaticus"], "A musty, sweet or fruity breath odor in advanced liver disease and encephalopathy."],
 ["Hepatorenal syndrome", ["epatorenal"], "Kidney failure caused by end-stage liver disease: urine output falls under 500 mL a day and BUN and creatinine rise. It carries a poor outlook."],
 ["Spontaneous bacterial peritonitis (SBP)", ["pontaneous bacterial", "SBP"], "Infection of ascitic fluid by gut bacteria that crossed the bowel wall. Signs can be fever and belly pain — or only more confusion. Found by paracentesis."],
 ["Paracentesis", ["aracentesis"], "Draining fluid from the abdomen through a needle or catheter. The patient voids first and is weighed before and after."],
 ["TIPS", ["TIPS", "ransjugular intrahepatic"], "Transjugular intrahepatic portal-systemic shunt: a stent placed through the liver from the jugular vein to connect the portal vein to a hepatic vein, lowering portal pressure. Encephalopathy can follow."],
 ["Variceal banding (ligation)", ["ariceal ligation", "banding", "EVL"], "Small rubber bands placed around varices through an endoscope to cut off their blood supply and stop or prevent bleeding."],
 ["Sclerotherapy", ["clerotherapy"], "Injecting a scarring agent into bleeding varices through an endoscope to seal them; it can cause ulcers in the lining."],
 ["Balloon tamponade", ["alloon tamponade"], "A tube with a balloon passed through the nose into the stomach; inflating it presses on bleeding varices. The airway is protected first because it can cause aspiration or asphyxia."],
 ["Spider angioma / palmar erythema", ["pider angioma", "almar erythema"], "Skin signs of chronic liver disease: small red spots with spidery branches on the face and chest, and warm, bright red palms."],
 ["Icterus", ["cterus"], "Yellowing of the whites of the eyes from high bilirubin — often seen before the skin turns yellow."],
 ["Pruritus", ["ruritus"], "Itching. In liver and gallbladder disease it comes from bilirubin and bile salts in the skin."],
 ["Transient elastography", ["lastography"], "An ultrasound test that measures how stiff the liver is: about 5 kPa is normal and more than 13 kPa means cirrhosis."],
 ["Alcohol withdrawal / DTs", ["lcohol withdrawal", "elirium tremens", "DTs"], "Symptoms after heavy drinking stops: tremors from 6\u20138 hours, then possibly delirium tremens \u2014 confusion, hallucinations, fast heart rate, high BP and sweating. It can be an emergency."],
 ["NAFLD / NASH", ["NAFLD", "NASH", "atty liver"], "Fat building up in the liver without alcohol use, tied to obesity and diabetes (now also called MASLD). NASH is the inflamed, scarring form that can lead to cirrhosis."],
 ["Hepatitis", ["epatitis"], "Inflammation of the liver, most often from a virus (A, B, C, D or E). A and E spread through contaminated food or water; B, C and D through blood and body fluids."],
 ["HBsAg / anti-HBs", ["HBsAg", "anti-HBs"], "HBsAg is a piece of the hepatitis B virus \u2014 while it is in the blood, the person is infectious. Anti-HBs is the antibody against it \u2014 a sign of recovery or vaccination."],
 ["Direct-acting antivirals (DAAs)", ["irect-acting antiviral", "DAA"], "Pills that block hepatitis C\u2019s own proteins and cure most infections in weeks. Ask about hepatitis B first \u2014 it can flare up."],
 ["Fulminant hepatitis", ["ulminant"], "Sudden, severe hepatitis in which liver cells die faster than they can regrow; often fatal without a transplant."],
 ["Immune globulin", ["mmune globulin"], "Ready-made antibodies given after an exposure (e.g., within 14 days of hepatitis A) for short-term protection."],
 ["Graft rejection", ["rejection"], "The immune system attacking a transplanted organ. After a liver transplant it usually shows at 7\u201314 days: fever, fast pulse, right-side pain, less bile, rising jaundice."],
 ["T-tube", ["T-tube"], "A drain placed in the bile duct during surgery that carries bile to a bag outside. Keep it below the site and record the bile\u2019s amount and color."],
 // Gallbladder and pancreas (ch 51)
 ["Cholelithiasis / choledocholithiasis", ["holelithiasis", "holedocholithiasis", "allstone"], "Gallstones in the gallbladder / a gallstone stuck in the common bile duct. Most are cholesterol stones."],
 ["Cholecystitis", ["holecystitis"], "Inflammation of the gallbladder, usually because a gallstone blocks the cystic duct. Pain is in the right upper abdomen, often after a fatty meal."],
 ["Calculous vs acalculous", ["calculous"], "With stones (calculous, about 95%) or without them (acalculous) \u2014 the second happens in very sick patients: sepsis, burns, long-term TPN."],
 ["Biliary colic", ["iliary colic"], "Severe right upper abdominal pain as a gallstone moves or lodges in a duct and the duct spasms around it. It can bring on sweating, pallor and shock."],
 ["Murphy sign", ["urphy"], "Pain that makes the patient stop a deep breath while the examiner presses under the right rib edge \u2014 a sign of cholecystitis (checked by the provider)."],
 ["Blumberg sign", ["lumberg"], "Rebound tenderness \u2014 pain when deep pressure on the abdomen is suddenly let go, a sign of peritoneal inflammation."],
 ["Cholangitis", ["holangitis"], "Infection and inflammation of the bile ducts; with pus (suppurative cholangitis) it is life-threatening."],
 ["HIDA scan", ["HIDA", "epatobiliary scan"], "A nuclear scan: a tracer is injected and a camera watches it leave the gallbladder. Low emptying means disease or a blockage. NPO beforehand."],
 ["MRCP", ["MRCP"], "An MRI of the bile and pancreatic ducts using gadolinium contrast \u2014 safer than ERCP. No MRI with a pacemaker."],
 ["Cholecystectomy", ["holecystectomy", "lap chole"], "Surgery to remove the gallbladder, usually laparoscopic and same-day. Carbon dioxide used during it can cause shoulder pain afterward."],
 ["Postcholecystectomy syndrome", ["ostcholecystectomy", "PCS"], "Abdominal pain with vomiting or diarrhea weeks to months after the gallbladder is removed \u2014 often a retained stone or a duct problem found by ERCP."],
 ["Sphincter of Oddi", ["of Oddi"], "The muscle ring where the bile and pancreatic ducts empty into the duodenum. Opioids can make it spasm."],
 ["Cholecystokinin (CCK)", ["holecystokinin", "CCK"], "A gut hormone released when fat reaches the duodenum; it squeezes the gallbladder \u2014 why fatty meals trigger gallbladder pain."],
 ["Autodigestion", ["utodigestion"], "The pancreas digesting itself when its enzymes switch on inside the gland instead of in the intestine \u2014 the core of acute pancreatitis."],
 ["Fat necrosis", ["at necrosis"], "Fat tissue destroyed by the enzyme lipase. The freed fatty acids bind calcium, so blood calcium drops."],
 ["Necrotizing hemorrhagic pancreatitis", ["ecrotizing hemorrhagic", "NHP"], "The most severe form of acute pancreatitis: the gland bleeds and dies, and multiorgan failure can follow."],
 ["Pancreatic pseudocyst", ["seudocyst"], "A pocket of pancreatic fluid walled off by fibrous tissue after pancreatitis; it can rupture or need drainage."],
 ["ARDS", ["ARDS"], "Acute respiratory distress syndrome: the lungs\u2019 tiny air sacs leak fluid, so oxygen falls fast. A leading cause of death early in acute pancreatitis."],
 ["DIC", ["DIC"], "Disseminated intravascular coagulation: clotting runs out of control, using up clotting factors, so the patient clots and bleeds at once."],
 ["Pancreatic enzyme replacement (PERT)", ["PERT", "nzyme replacement"], "Capsules of lipase, protease and amylase taken with every meal and snack, swallowed whole, so food is digested; fewer, less fatty stools show they work."],
 ["Whipple procedure", ["hipple", "ancreaticoduodenectomy"], "Major surgery for cancer in the head of the pancreas: the head, duodenum, part of the jejunum and stomach, and the gallbladder are removed and the ducts rejoined to the jejunum."],
 ["Pancreatectomy", ["ancreatectomy"], "Removal of part (distal, partial) or all (total, radical) of the pancreas. After a total pancreatectomy the patient needs insulin."],
 ["CA 19-9", ["CA 19-9"], "A tumor marker used to follow pancreatic cancer treatment and watch for recurrence \u2014 not to diagnose it."],
 ["Endoscopic ultrasound (EUS)", ["EUS", "ndoscopic ultrasound"], "An ultrasound probe on an endoscope that looks at the pancreas from inside the stomach and duodenum \u2014 the gold standard for finding pancreatic tumors."],
 ["Jejunostomy", ["ejunostomy"], "A feeding tube placed through the abdominal wall into the jejunum, past the stomach \u2014 used when the stomach shouldn\u2019t be used or can\u2019t empty."],
 // Nutrition (ch 52)
 ["Malnutrition", ["alnutrition", "alnourish"], "Too little, too much or the wrong balance of energy and nutrients \u2014 undernutrition and obesity are both forms of it."],
 ["Protein-energy undernutrition (PEU)", ["PEU", "rotein-energy"], "Not enough calories and/or protein; its forms are marasmus and kwashiorkor, and starvation is the most severe."],
 ["Marasmus", ["arasmus"], "Calorie starvation: fat and muscle waste away, but blood proteins are often still normal."],
 ["Kwashiorkor", ["washiorkor"], "Protein starvation with enough calories: weight looks more normal, but blood proteins are low and swelling (edema) appears."],
 ["Cachexia", ["achexia"], "Extreme wasting of muscle and fat from illness such as cancer \u2014 intake can\u2019t keep up with what the body burns."],
 ["BMI (body mass index)", ["BMI", "ody mass index"], "Weight in kg divided by height in meters squared. Under 18.5 underweight, 18.5\u201324.9 normal, 25\u201329.9 overweight, 30 or more obese."],
 ["Body surface area (BSA)", ["BSA", "ody surface area"], "An estimate of skin surface from height and weight, used to dose chemotherapy and judge burns."],
 ["MNA (Mini Nutritional Assessment)", ["MNA", "ini Nutritional"], "A short screening form for older adults that scores eating, weight loss, mobility, stress, BMI and more to find malnutrition."],
 ["Anthropometric measurements", ["nthropometric"], "Body measurements \u2014 height, weight, BMI, skinfolds, arm and calf circumference \u2014 used to judge nutrition."],
 ["Prealbumin / transferrin", ["realbumin", "ransferrin"], "Blood proteins made by the liver that fall when protein intake is poor; prealbumin changes within days, faster than albumin."],
 ["Tube feeding (TEN)", ["TEN", "tube feeding"], "Liquid formula given through a tube into the stomach or small intestine when a person can\u2019t eat enough by mouth."],
 ["Bolus, continuous and cyclic feeding", ["olus feeding", "ontinuous feeding", "yclic feeding"], "Ways to run a tube feeding: a set amount every few hours (bolus), nonstop by pump (continuous), or nonstop with a daily break of 6 hours or more (cyclic)."],
 ["Gastric residual", ["esidual"], "Formula left in the stomach, drawn back with a syringe to see whether the stomach is emptying; a large amount means slow or stop the feeding."],
 ["PEG tube", ["PEG tube", "astrostomy", "PEG/J"], "A feeding tube placed through the abdominal wall into the stomach with an endoscope, for long-term feeding. Rotate it daily; if it won\u2019t turn, report it."],
 ["Parenteral nutrition (TPN / PPN)", ["TPN", "PPN", "arenteral"], "Nutrition given into a vein when the gut can\u2019t be used: PPN through a large arm vein for a short time, TPN (concentrated, high in glucose) through a central line."],
 ["Refeeding syndrome", ["efeeding"], "A dangerous shift when a starved person is fed too fast: phosphate, potassium and magnesium rush into cells, causing heart failure, swelling, seizures or breathing failure."],
 ["Fat overload syndrome", ["at overload"], "A reaction to IV fat (lipid) infusions: fever, high triglycerides, clotting problems, organ failure. Stop the lipid and report."],
 ["Food allergy vs intolerance", ["ood allergy", "ood intolerance", "actose intolerance"], "An allergy is an immune reaction that can cause anaphylaxis (nuts, peanuts, shellfish); an intolerance is a digestive problem such as lactose intolerance \u2014 gas, bloating, diarrhea."],
 ["Obesity", ["bese", "besity"], "A BMI of 30 or more: class I 30\u201334.9, class II 35\u201339.9, class III 40 or more. Fat around the waist carries the most risk."],
 ["Waist circumference", ["aist circumference", "aist-to-hip"], "A measure of belly fat: more than 35 inches in women or 40 inches in men means central obesity, which predicts heart disease better than BMI."],
 ["Intertrigo", ["ntertrigo"], "Redness and yeast (Candida) infection in moist skinfolds, such as under the breasts or an abdominal apron."],
 ["Panniculus / panniculectomy", ["anniculus", "anniculectomy", "anniculitis"], "The apron of skin and fat hanging over the lower abdomen; panniculectomy removes it, usually 18\u201324 months after weight loss surgery."],
 ["Bariatric surgery", ["ariatric"], "Weight-loss surgery that shrinks or bypasses the stomach \u2014 for example a sleeve gastrectomy or a gastric bypass."],
 ["Roux-en-Y gastric bypass", ["oux-en-Y", "astric bypass", "RNYGB"], "The most common US weight-loss surgery: a small stomach pouch is joined to the jejunum, bypassing the rest of the stomach and the duodenum."],
 ["Sleeve gastrectomy", ["leeve gastrectomy", "leeve gastroplasty"], "Weight-loss surgery that removes about three-fourths of the stomach, leaving a narrow tube."],
 ["Anastomotic leak", ["nastomotic leak"], "Digestive juice leaking where two parts of the gut were sewn together \u2014 the most dangerous complication after gastric bypass: rising back, shoulder or belly pain, fast pulse, low urine output."],
 ["Eating disorders", ["norexia nervosa", "ulimia", "inge eating"], "Anorexia nervosa (starving from fear of fatness), bulimia nervosa (binges followed by purging) and binge eating disorder (binges with loss of control, no purging)."],
 ["Food desert", ["ood desert"], "An area where fresh, healthy food is scarce or too expensive to buy."],
 // Endocrine glands and tests (ch 53)
 ["Hormone", ["hormone"], "A chemical messenger released into the blood that acts only on cells with a matching receptor."],
 ["Negative feedback", ["egative feedback"], "A loop in which the result switches off its own trigger — for example, high thyroid hormone switches off TSH."],
 ["Hypothalamus", ["ypothalam"], "The brain area that controls the pituitary with releasing and inhibiting hormones."],
 ["Pituitary gland", ["ituitar"], "The “master gland” under the brain. The anterior part makes TSH, ACTH, FSH, LH, growth hormone and prolactin; the posterior part stores ADH and oxytocin."],
 ["TSH", ["TSH"], "Thyroid-stimulating hormone from the pituitary. High TSH = the thyroid itself is underactive; low TSH = too much thyroid hormone (as in Graves)."],
 ["T₃ / T₄", ["T₃", "T₄", "T3", "T4"], "The thyroid hormones. The gland makes mostly T₄ (thyroxine); cells convert it to T₃, the more active form. Together they set the speed of metabolism."],
 ["ACTH / cortisol", ["ACTH", "ortisol"], "ACTH from the pituitary tells the adrenal glands to make cortisol, the stress hormone that raises glucose and calms inflammation."],
 ["Catecholamines", ["atecholamine"], "Epinephrine and norepinephrine from the adrenal medulla — the fight-or-flight hormones."],
 ["Stimulation vs suppression test", ["timulation test", "uppression test", "rovocative"], "Stimulation: give what should switch a gland on — no rise means it is underactive. Suppression: give what should switch it off — no fall means it is overactive."],
 ["24-hour urine", ["24-hour urine"], "Collecting every drop of urine for 24 hours (discard the first void, keep the last) to measure hormones that are released in pulses."],
 ["Buffalo hump / striae", ["uffalo hump", "triae"], "Fat at the back of the neck and reddish-purple stretch marks — signs of too much cortisol."],
 ["Hirsutism / gynecomastia", ["irsutism", "ynecomastia"], "Excess male-pattern hair in women / breast tissue growth in men — signs of hormone imbalance."],
 ["Vitiligo", ["itiligo"], "Patches of skin with no pigment from autoimmune loss of pigment cells — linked to autoimmune adrenal and thyroid disease."],
 ["Fine needle aspiration (FNA)", ["ine needle aspiration", "FNA"], "Using a thin needle, guided by ultrasound, to take cells from a thyroid nodule and see whether it is cancer."],
 // Thyroid and parathyroid (ch 55)
 ["Goiter", ["oiter"], "An enlarged thyroid gland. It can occur with too little or too much thyroid hormone, so it doesn’t tell you which."],
 ["Exophthalmos", ["xophthalm"], "Bulging eyes from swelling behind the eye — seen only in Graves disease. The lids may not close, so the cornea can dry and ulcerate."],
 ["Lid lag / globe lag", ["id lag", "lobe lag"], "The upper lid not following the eye down (lid lag) or pulling back too fast when looking up (globe lag) — signs of hyperthyroidism."],
 ["Graves disease", ["Graves"], "Autoimmune hyperthyroidism: antibodies switch on the TSH receptor, so the gland grows and overproduces hormone. Only Graves causes exophthalmos."],
 ["Hashimoto thyroiditis", ["ashimoto"], "Autoimmune destruction of the thyroid — the most common cause of hypothyroidism in the US."],
 ["Thyroid storm", ["hyroid storm", "hyroid crisis"], "A life-threatening surge of thyroid hormone: high fever, very fast heart, agitation, delirium. In a hyperthyroid patient, even a 1°F temperature rise is reported."],
 ["Myxedema", ["yxedema"], "Swelling of the skin and tissues from water-holding compounds in hypothyroidism — puffy face, thick tongue, nonpitting edema. Myxedema coma is the life-threatening extreme."],
 ["Euthyroid", ["uthyroid"], "Having normal thyroid hormone levels."],
 ["Thionamides", ["hionamide"], "Antithyroid drugs (methimazole, PTU) that stop the thyroid from making new hormone."],
 ["Radioactive iodine (RAI)", ["adioactive iodine", "RAI"], "Swallowed iodine-131 that the thyroid takes up; its radiation destroys some hormone-making cells. Home precautions for about a week; never in pregnancy."],
 ["Thyroidectomy", ["hyroidectomy"], "Surgical removal of part or all of the thyroid. Watch the airway, bleeding behind the neck, the voice and calcium."],
 ["Recurrent laryngeal nerve", ["aryngeal nerve"], "The nerve to the vocal cords, running beside the thyroid. Injury causes hoarseness; damage on both sides can close the airway."],
 ["Tetany", ["etany"], "Muscle twitching, cramps and spasms (hands, feet, larynx) from low calcium."],
 ["Chvostek sign", ["hvostek"], "Tapping in front of the ear makes the face twitch — a sign of low calcium."],
 ["Trousseau sign", ["rousseau"], "A BP cuff inflated on the arm makes the hand and wrist spasm — a sign of low calcium."],
 ["Carpopedal spasm", ["arpopedal"], "Cramping that flexes the hands and feet — a sign of low calcium."],
 ["Hypocalcemia / hypercalcemia", ["ypocalcemia", "ypercalcemia"], "Low calcium makes nerves too excitable (tingling, tetany, seizures); high calcium slows them (weakness, constipation, confusion) and forms kidney stones."],
 ["PTH (parathyroid hormone)", ["PTH", "arathyroid hormone"], "The parathyroid glands’ hormone, which raises blood calcium by pulling it from bone, holding it in the kidney and absorbing more from food."],
 ["Hypo- / hyperparathyroidism", ["ypoparathyroid", "yperparathyroid"], "Too little PTH (low calcium, often after neck surgery) or too much PTH (high calcium, kidney stones, bone loss)."],
 ["Calcitonin", ["alcitonin"], "A thyroid hormone that lowers blood calcium by keeping it in bone — the opposite of PTH."],
 ["Calcitriol", ["alcitriol"], "The active form of vitamin D, made in the kidney. It increases calcium absorption from food."],
 // Diabetes (ch 56)
 ["Diabetes mellitus", ["iabetes mellitus"], "A failure of glucose regulation: no insulin (type 1), or insulin the body resists and slowly fails to make enough of (type 2)."],
 ["Type 1 vs type 2 diabetes", ["ype 1 diabetes", "ype 2 diabetes", "T1DM", "T2DM"], "Type 1: autoimmune loss of the insulin-making cells; needs insulin; prone to DKA. Type 2: insulin resistance, then declining insulin; often found by screening."],
 ["Prediabetes", ["rediabetes"], "Glucose higher than normal but not yet diabetes: A1C 5.7–6.4%, fasting 100–125. Losing 5–10% of body weight, 150 minutes of activity a week, more fiber and no sugary drinks can prevent or delay type 2."],
 ["Gestational diabetes", ["estational diabetes", "GDM"], "Diabetes first found in pregnancy. It raises the mother’s lifelong type 2 risk — test every 3 years."],
 ["Insulin resistance", ["nsulin resistance"], "Cells respond poorly to insulin, so the pancreas must make more to keep glucose normal — the start of type 2."],
 ["Beta cells / islets", ["eta cell", "slets", "slet cell"], "The insulin-making cells in the pancreas’s islets of Langerhans (alpha cells there make glucagon)."],
 ["Glucagon", ["lucagon"], "The “hormone of starvation” from the pancreas: it tells the liver to release glucose. Also an emergency injection for severe lows."],
 ["Incretins (GLP-1)", ["ncretin", "GLP-1"], "Gut hormones released with food that boost insulin, lower glucagon and slow the stomach. Semaglutide and similar drugs copy them."],
 ["A1C", ["A1C", "HbA1c"], "The percentage of hemoglobin with glucose stuck to it — an average of the last ~3 months. ≥ 6.5% = diabetes; target < 7%."],
 ["OGTT", ["OGTT", "ral glucose tolerance"], "Oral glucose tolerance test: drink 75 g of glucose and check glucose 2 hours later; ≥ 200 = diabetes."],
 ["CGM", ["CGM", "ontinuous glucose monitor"], "A sensor under the skin that reads glucose every few minutes. It lags behind blood glucose during fast changes — confirm extremes with a fingerstick."],
 ["Time in range", ["ime in range"], "The share of the day CGM glucose stays between 70 and 180 mg/dL; the goal is at least 70%."],
 ["Polyuria / polydipsia / polyphagia", ["olyuria", "olydipsia", "olyphagia"], "Too much urine, too much thirst and too much hunger — the 3 Ps of high glucose."],
 ["Osmotic diuresis", ["smotic diuresis"], "Glucose spilling into the urine pulls water and electrolytes with it — the cause of polyuria and dehydration."],
 ["Ketones", ["etone"], "Acids made when the body burns fat for fuel because insulin is missing. Their build-up causes DKA; acetone gives the breath a fruity smell."],
 ["DKA (diabetic ketoacidosis)", ["DKA", "etoacidosis"], "Uncontrolled high glucose + ketones + acid blood from too little insulin, often with illness. Kussmaul breathing, fruity breath, vomiting. Fluids first, then IV insulin; watch potassium."],
 ["Kussmaul respirations", ["ussmaul"], "Deep, rapid breathing that blows off CO₂ to make up for acid blood in DKA."],
 ["Anion gap", ["nion gap"], "A lab calculation (sodium minus chloride and bicarbonate) that rises when extra acids such as ketones are in the blood."],
 ["HHS", ["HHS", "yperosmolar"], "Hyperglycemic-hyperosmolar state: glucose > 600 and extreme dehydration without ketones, mostly in older adults with type 2. The brain is the danger."],
 ["Osmolarity", ["smolarity", "smolality"], "How concentrated the blood is (normal 270–300). High glucose raises it and pulls water out of brain cells."],
 ["Hypoglycemia", ["ypoglycemi"], "Blood glucose below 70: shaky, sweaty, hungry, fast heart, then confusion and seizures. Treat at once with 15 g of fast sugar."],
 ["Hypoglycemic unawareness", ["ypoglycemic unawareness", "ypoglycemia unawareness"], "Having lows without the warning shakiness and sweating — common with long-standing diabetes or beta blockers."],
 ["15-15 rule", ["15-15"], "For a low: 15 g of fast carbohydrate, recheck in 15 minutes, repeat if still below 70, then a snack with protein."],
 ["Dawn phenomenon / Somogyi effect", ["awn phenomenon", "omogyi"], "Both cause high morning glucose. Dawn: early-morning hormones (more overnight insulin). Somogyi: a rebound from a low in the night (less insulin, bedtime snack)."],
 ["Basal / bolus insulin", ["asal insulin", "olus insulin", "asal-bolus"], "Basal: steady background insulin for between meals and overnight. Bolus: rapid insulin to cover a meal, plus a correction for a high reading."],
 ["Correction dose", ["orrection dose", "orrection factor", "liding scale"], "Extra rapid insulin added to bring a high reading down."],
 ["Insulin-to-carbohydrate ratio", ["nsulin-to-carb"], "How many grams of carbohydrate one unit of rapid insulin covers — for example, 1 unit per 15 g."],
 ["Lipohypertrophy", ["ipohypertroph"], "Lumpy fat under the skin from injecting insulin in the same spot; insulin absorbs unevenly there."],
 ["Insulin pump (CSII)", ["nsulin pump", "CSII"], "A device that gives rapid insulin continuously through a tiny catheter, plus meal doses. Blocked tubing can lead to DKA within hours."],
 ["Sick-day rules", ["ick-day", "ick day"], "When ill: keep taking insulin, check glucose every 2–4 hours and check ketones, drink 8–12 oz of sugar-free, caffeine-free fluid every hour, take carbohydrate as liquids or soft foods if meals won’t stay down (at least 150 g a day), and call for vomiting, ketones or glucose that stays high."],
 ["Retinopathy", ["etinopathy"], "Damage to the retina’s small vessels from diabetes — leaks, bleeding, fragile new vessels; it can cause blindness. Yearly eye exams."],
 ["Nephropathy", ["ephropathy"], "Kidney damage from diabetes, first seen as albumin in the urine — the leading cause of kidney failure in the US."],
 ["Neuropathy", ["europathy"], "Nerve damage from diabetes: numb, tingling or burning feet (peripheral); slow stomach, dizziness on standing, bladder problems (autonomic)."],
 ["Gastroparesis", ["astroparesis"], "A slow-emptying stomach from nerve damage: fullness, nausea, vomiting — and lows, because food arrives later than the insulin."],
 ["Charcot foot", ["harcot"], "Weakened bones in a numb foot collapse; the foot becomes warm, swollen and deformed (“rocker bottom”)."],
 ["Monofilament test", ["onofilament"], "Touching the foot with a thin nylon filament; if it can’t be felt, protective sensation is lost and ulcer risk is high."],
 ["Albuminuria", ["lbuminuria"], "Albumin in the urine — the earliest sign of diabetic kidney damage."],
 ["Macrovascular / microvascular", ["acrovascular", "icrovascular"], "Large-vessel disease (heart attack, stroke, PAD) vs small-vessel disease (eyes, kidneys, nerves)."],
 ["Metabolic syndrome", ["etabolic syndrome"], "A cluster — large waist, high glucose, high BP, high triglycerides, low HDL — that raises the risk of type 2 diabetes and heart disease."],
 ["Fournier gangrene", ["ournier"], "A rare, severe infection of the genital and perineal area linked to SGLT2 inhibitors — report swelling, redness or tenderness at once."],
 ["Lactic acidosis", ["actic acidosis"], "Acid build-up from lactate; a rare, serious risk of metformin when the kidneys can’t clear it."],
 ["Medical nutrition therapy", ["edical nutrition therapy"], "An eating plan built with a dietitian around the person’s foods, culture, budget and medicines."],
 ["Carbohydrate counting", ["arb counting", "arbohydrate counting"], "Adding up the grams of carbohydrate in a meal to match the insulin dose."]
], window.GLOSSARY || []);
